package javax.microedition.lcdui.game;import javax.microedition.lcdui.*;
public class TiledLayer extends Layer {private int columns,rows,tw,th;private int[]cells;private java.util.Vector animated=new java.util.Vector();private Image image;
 public TiledLayer(int cols,int rows,Image image,int w,int h){super(cols*w,rows*h);if(cols<1||rows<1)throw new IllegalArgumentException();columns=cols;this.rows=rows;cells=new int[cols*rows];setStaticTileSet(image,w,h);}
 public int getColumns(){return columns;}public int getRows(){return rows;}public int getCellWidth(){return tw;}public int getCellHeight(){return th;}
 public void setStaticTileSet(Image im,int w,int h){if(im==null||w<=0||h<=0||im.getWidth()%w!=0||im.getHeight()%h!=0)throw new IllegalArgumentException();image=im;tw=w;th=h;width=columns*w;height=rows*h;for(int i=0;i<cells.length;i++)if(cells[i]>count())cells[i]=0;}
 private int count(){return image.getWidth()/tw*(image.getHeight()/th);}private void valid(int tile){if(tile>count()||tile< -animated.size())throw new IndexOutOfBoundsException();}public int createAnimatedTile(int tile){if(tile<0||tile>count())throw new IndexOutOfBoundsException();animated.addElement(Integer.valueOf(tile));return -animated.size();}public int getAnimatedTile(int index){return ((Integer)animated.elementAt(-index-1)).intValue();}public void setAnimatedTile(int index,int tile){if(tile<0||tile>count())throw new IndexOutOfBoundsException();animated.setElementAt(Integer.valueOf(tile),-index-1);}
 public int getCell(int col,int row){if(col<0||col>=columns||row<0||row>=rows)throw new IndexOutOfBoundsException();return cells[row*columns+col];}public void setCell(int col,int row,int tile){valid(tile);getCell(col,row);cells[row*columns+col]=tile;}public void fillCells(int col,int row,int cols,int rs,int tile){valid(tile);if(cols<0||rs<0)throw new IllegalArgumentException();for(int yy=row;yy<row+rs;yy++)for(int xx=col;xx<col+cols;xx++)setCell(xx,yy,tile);}
 public void paint(Graphics g){if(!isVisible())return;int left=Math.max(0,(g.getClipX()-x)/tw),top=Math.max(0,(g.getClipY()-y)/th),right=Math.min(columns,(g.getClipX()+g.getClipWidth()-x+tw-1)/tw),bottom=Math.min(rows,(g.getClipY()+g.getClipHeight()-y+th-1)/th);for(int row=top;row<bottom;row++)for(int col=left;col<right;col++){int tile=getCell(col,row);if(tile<0)tile=getAnimatedTile(tile);if(tile==0)continue;tile--;g.drawRegion(image,tile%(image.getWidth()/tw)*tw,tile/(image.getWidth()/tw)*th,tw,th,0,x+col*tw,y+row*th,20);}}
 boolean collides(Sprite s,boolean pixels){for(int row=0;row<rows;row++)for(int col=0;col<columns;col++){int tile=getCell(col,row);if(tile<0)tile=getAnimatedTile(tile);if(tile==0)continue;int px=x+col*tw,py=y+row*th;if(px>=s.getX()+s.getWidth()||px+tw<=s.getX()||py>=s.getY()+s.getHeight()||py+th<=s.getY())continue;if(!pixels)return true;int f=tile-1;Image cell=Image.createImage(image,f%(image.getWidth()/tw)*tw,f/(image.getWidth()/tw)*th,tw,th,0);if(s.collidesWith(cell,px,py,true))return true;}return false;}}
